#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>
#include <errno.h>

#define MAX_VALUE 0xBFA17DC6ULL
static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};

static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
#if defined(__SIZEOF_INT128__)
    __uint128_t res = ( (__uint128_t) a * b ) % mod;
    return (uint64_t)res;
#else
    uint64_t result = 0;
    a %= mod;
    while (b) {
        if (b & 1) {
            result = (result + a) % mod;
        }
        a = (a << 1) % mod;
        b >>= 1;
    }
    return result;
#endif
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

static int miller_rabin_pass(uint64_t n, uint64_t a)
{
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    uint64_t x = pow_mod(a, d, n);
    if (x == 1 || x == n - 1)
        return 1;
    for (unsigned int r = 1; r < s; ++r) {
        x = mul_mod(x, x, n);
        if (x == n - 1)
            return 1;
    }
    return 0;
}

static int is_prime(uint64_t n)
{
    if (n < 2)
        return 0;
    if (n % 2 == 0)
        return n == 2;
    if (n % 3 == 0)
        return n == 3;
    if (n % 5 == 0)
        return n == 5;
    if (n % 7 == 0)
        return n == 7;
    if (n % 11 == 0)
        return n == 11;
    if (n % 13 == 0)
        return n == 13;
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a >= n) break;
        if (!miller_rabin_pass(n, a))
            return 0;
    }
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    errno = 0;
    long long ll = strtoll(argv[1], &endptr, 10);
    if (errno != 0 || endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    uint64_t n = (uint64_t) ll;
    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");
    return 0;
}
